// Verify: original GetPivotPosition + safety net behaviour on Tower(17 corners) and Cubes
var tower = GameObject.Find("TowerB (9)");
if (tower == null) return "TowerB (9) not found";
var es = tower.transform.Find("EdgeSearch");
if (es == null) return "EdgeSearch not found";
var rs = es.GetComponent<RaySearch>();

Vector3 origin = new Vector3(-84.12f, 25.5f, 146.5f);
Vector3 toCenter = (tower.transform.position - origin); toCenter.y = 0; toCenter.Normalize();
rs.mergeMode = WallMerge.WallMergeMode.Current;
rs.DoPointsFromPlayer(origin, toCenter);

int N = rs.cornerPoints.Count;
var sb = new System.Text.StringBuilder();
sb.AppendLine($"TowerB (9): {N} corners, IsClosedLoop={rs.IsClosedLoop}");

// Need a ProjectorMovement to call GetPivotPosition. Find existing one.
var pm = UnityEngine.Object.FindFirstObjectByType<ProjectorMovement>();
if (pm == null) { sb.AppendLine("  no ProjectorMovement found"); return sb.ToString(); }

// Reflection to inject test state
var searchField = typeof(ProjectorMovement).GetField("search", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
searchField.SetValue(pm, rs);
var savedNormalField = typeof(ProjectorMovement).GetField("savedNormal", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

int badPivots = 0;
float maxDistFromDecal = 0f;
Vector3 fakeDecalPos = rs.cornerPoints[0].position; // start near first corner

for (int i = 0; i < N; i++)
{
    // Simulate: came from corner (i-1+N)%N, going right (to next)
    int prev = (i - 1 + N) % N;
    int next = (i + 1) % N;
    Vector3 origPos = rs.cornerPoints[prev].position;
    Vector3 targPos = rs.cornerPoints[next].position;
    var origPosField = typeof(ProjectorMovement).GetField("originPos", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    var targPosField = typeof(ProjectorMovement).GetField("targetPos", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
    origPosField.SetValue(pm, origPos);
    targPosField.SetValue(pm, targPos);
    savedNormalField.SetValue(pm, rs.cornerPoints[prev].normal);
    pm.transform.position = rs.cornerPoints[i].position; // pretend we're at corner i

    Vector3 pivot = pm.GetPivotPosition(i, true);
    float distFromCorner = Vector3.Distance(pivot, rs.cornerPoints[i].position);
    float distFromDecal = Vector3.Distance(pivot, pm.transform.position);
    if (distFromDecal > 50f || float.IsNaN(pivot.x))
    {
        badPivots++;
        sb.AppendLine($"  [BAD {i}] pivot={pivot}  distFromCorner={distFromCorner:F2}  distFromDecal={distFromDecal:F2}");
    }
    if (distFromDecal > maxDistFromDecal) maxDistFromDecal = distFromDecal;
}
sb.AppendLine($"badPivots={badPivots}/{N}, maxDistFromDecal={maxDistFromDecal:F2}m (safety net trips at >50m)");
return sb.ToString();
